* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  background: #f4f6f9;
  color: #333;
}

h1 {
  text-align: center;
  padding: 18px 0 6px;
  font-size: 1.6rem;
  color: #1a1a2e;
}

.container {
  display: flex;
  gap: 24px;
  padding: 12px 24px 24px;
  max-width: 1600px;
  margin: 0 auto;
  align-items: flex-start;
}

/* ---------- Bubble chart panel ---------- */
.chart-panel {
  flex: 1 1 55%;
  min-width: 0;
  background: #fff;
  border-radius: 8px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.08);
  padding: 16px;
}

.chart-panel h2 {
  font-size: 1.05rem;
  margin-bottom: 8px;
  color: #444;
}

#bubble-chart {
  width: 100%;
  position: relative;
}

#bubble-chart svg {
  display: block;
}

/* Bubble styling */
.bubble {
  cursor: pointer;
  stroke: #fff;
  stroke-width: 1.2px;
  transition: opacity 0.15s;
}

.bubble.selected {
  stroke: #222;
  stroke-width: 3px;
}

.bubble-label {
  pointer-events: none;
  text-anchor: middle;
  dominant-baseline: central;
  fill: #fff;
  font-weight: 600;
  font-size: 10px;
}

/* Tooltip */
.tooltip {
  position: absolute;
  padding: 10px 14px;
  background: rgba(20, 20, 40, 0.92);
  color: #fff;
  border-radius: 6px;
  font-size: 0.82rem;
  line-height: 1.5;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.15s;
  z-index: 100;
  white-space: nowrap;
}

.tooltip .tip-ticker {
  font-weight: 700;
  font-size: 0.95rem;
}

.tooltip .tip-name {
  color: #ccc;
}

/* Legend */
.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 16px;
  margin-top: 10px;
  padding: 6px 0;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 0.78rem;
  color: #555;
}

.legend-swatch {
  width: 14px;
  height: 14px;
  border-radius: 3px;
  flex-shrink: 0;
}

/* ---------- Table panel ---------- */
.table-panel {
  flex: 1 1 40%;
  min-width: 0;
  background: #fff;
  border-radius: 8px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.08);
  padding: 16px;
  max-height: 700px;
  overflow-y: auto;
}

.table-panel h2 {
  font-size: 1.05rem;
  margin-bottom: 8px;
  color: #444;
}

#stock-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.84rem;
}

#stock-table thead {
  position: sticky;
  top: 0;
  z-index: 2;
}

#stock-table th {
  background: #2c3e6b;
  color: #fff;
  padding: 10px 10px;
  text-align: left;
  font-weight: 600;
  white-space: nowrap;
}

#stock-table td {
  padding: 8px 10px;
  border-bottom: 1px solid #e8eaed;
  white-space: nowrap;
}

#stock-table tbody tr {
  cursor: pointer;
  transition: background 0.12s;
}

#stock-table tbody tr:hover {
  background: #eef2fa;
}

#stock-table tbody tr.selected {
  background: #d0dbf0;
  font-weight: 600;
}

#stock-table tbody tr:nth-child(even) {
  background: #fafbfc;
}

#stock-table tbody tr:nth-child(even):hover {
  background: #eef2fa;
}

#stock-table tbody tr.selected,
#stock-table tbody tr.selected:hover {
  background: #d0dbf0;
  font-weight: 600;
}

