/* ============================================================
   Stock Bubble Chart + Data Table  (D3 v6)
   ============================================================ */

(function () {
  "use strict";

  /* ---------- colour palette per sector ---------- */
  const SECTOR_COLORS = {
    "Information Technology": "#4285F4",
    "Industry":              "#34A853",
    "Energy":                "#EA4335",
    "Financial":             "#FBBC05",
    "ETF":                   "#8E44AD"
  };

  const sectorList = Object.keys(SECTOR_COLORS);
  const colorScale = d3.scaleOrdinal()
    .domain(sectorList)
    .range(sectorList.map(s => SECTOR_COLORS[s]));

  /* ---------- helpers ---------- */
  function fmtMarketCap(v) {
    if (v == null || isNaN(v) || v === "") return "—";
    v = +v;
    if (v >= 1e12) return (v / 1e12).toFixed(2) + "T";
    if (v >= 1e9)  return (v / 1e9).toFixed(2)  + "B";
    if (v >= 1e6)  return (v / 1e6).toFixed(2)  + "M";
    return v.toLocaleString();
  }

  /* ---------- load data ---------- */
  d3.csv("data/stock-descriptions.csv").then(function (raw) {
    const data = raw.map(d => ({
      ticker:    d.ticker,
      name:      d["full name"],
      sector:    d.sector,
      marketCap: d.marketCap === "" ? null : +d.marketCap,
      country:   d.country  || null,
      website:   d.website  || null
    }));

    drawBubbleChart(data);
    drawTable(data);
  });

  /* ============================================================
     BUBBLE CHART
     ============================================================ */
  function drawBubbleChart(data) {
    const container = document.getElementById("bubble-chart");
    const width  = container.clientWidth || 720;
    const height = 580;

    /* --- radius scale --- */
    const caps = data.filter(d => d.marketCap != null).map(d => d.marketCap);
    const radiusScale = d3.scaleSqrt()
      .domain([d3.min(caps), d3.max(caps)])
      .range([12, 52]);

    const ETF_RADIUS = 14;

    function r(d) {
      return d.marketCap != null ? radiusScale(d.marketCap) : ETF_RADIUS;
    }

    /* --- sector centre positions (grid layout) --- */
    const sectorCenters = {};
    const cols = 3;
    const rows = Math.ceil(sectorList.length / cols);
    const cellW = width / cols;
    const cellH = height / rows;
    sectorList.forEach((s, i) => {
      const col = i % cols;
      const row = Math.floor(i / cols);
      sectorCenters[s] = {
        x: cellW * (col + 0.5),
        y: cellH * (row + 0.5)
      };
    });

    /* --- SVG --- */
    const svg = d3.select("#bubble-chart")
      .append("svg")
      .attr("width", width)
      .attr("height", height);

    /* --- tooltip --- */
    const tooltip = d3.select("#bubble-chart")
      .append("div")
      .attr("class", "tooltip");

    /* --- force simulation --- */
    const simulation = d3.forceSimulation(data)
      .force("x", d3.forceX(d => sectorCenters[d.sector].x).strength(0.35))
      .force("y", d3.forceY(d => sectorCenters[d.sector].y).strength(0.35))
      .force("collide", d3.forceCollide(d => r(d) + 2).iterations(3))
      .force("charge", d3.forceManyBody().strength(-2))
      .on("tick", ticked);

    /* --- nodes group --- */
    const node = svg.selectAll(".node")
      .data(data)
      .join("g")
      .attr("class", "node");

    node.append("circle")
      .attr("class", "bubble")
      .attr("r", d => r(d))
      .attr("fill", d => colorScale(d.sector))
      .attr("data-ticker", d => d.ticker);

    node.append("text")
      .attr("class", "bubble-label")
      .text(d => d.ticker)
      .style("font-size", d => Math.max(8, Math.min(r(d) * 0.55, 14)) + "px");

    /* --- interactions --- */
    node.on("mouseover", function (event, d) {
        if (d.sector === "ETF") return;          // no tooltip for ETFs
        tooltip
          .style("opacity", 1)
          .html(
            '<span class="tip-ticker">' + d.ticker + "</span><br>" +
            '<span class="tip-name">' + d.name + "</span><br>" +
            "Sector: " + d.sector
          );
      })
      .on("mousemove", function (event) {
        const bounds = container.getBoundingClientRect();
        tooltip
          .style("left", (event.clientX - bounds.left + 14) + "px")
          .style("top",  (event.clientY - bounds.top  - 10) + "px");
      })
      .on("mouseout", function () {
        tooltip.style("opacity", 0);
      })
      .on("click", function (event, d) {
        selectStock(d.ticker);
      });

    function ticked() {
      node.attr("transform", d => {
        d.x = Math.max(r(d), Math.min(width - r(d), d.x));
        d.y = Math.max(r(d), Math.min(height - r(d), d.y));
        return "translate(" + d.x + "," + d.y + ")";
      });
    }

    /* --- legend --- */
    const legend = d3.select("#bubble-chart")
      .append("div")
      .attr("class", "legend");

    sectorList.forEach(s => {
      const item = legend.append("span").attr("class", "legend-item");
      item.append("span")
        .attr("class", "legend-swatch")
        .style("background", SECTOR_COLORS[s]);
      item.append("span").text(s);
    });

    /* --- expose highlight helper --- */
    window._highlightBubble = function (ticker) {
      node.select("circle")
        .classed("selected", d => d.ticker === ticker);
    };
  }

  /* ============================================================
     DATA TABLE
     ============================================================ */
  function drawTable(data) {
    const table = d3.select("#stock-table");

    /* head */
    table.append("thead").append("tr")
      .selectAll("th")
      .data(["Ticker symbol", "Full company name", "Sector", "Market cap"])
      .join("th")
      .text(d => d);

    /* body */
    const tbody = table.append("tbody");
    const rows = tbody.selectAll("tr")
      .data(data)
      .join("tr")
      .attr("data-ticker", d => d.ticker);

    rows.append("td").text(d => d.ticker);
    rows.append("td").text(d => d.name);
    rows.append("td").text(d => d.sector);
    rows.append("td").text(d => fmtMarketCap(d.marketCap));

    rows.on("click", function (event, d) {
      selectStock(d.ticker);
    });

    /* --- expose highlight helper --- */
    window._highlightRow = function (ticker) {
      rows.classed("selected", d => d.ticker === ticker);
      /* scroll selected row into view */
      const sel = tbody.select("tr.selected").node();
      if (sel) sel.scrollIntoView({ block: "nearest", behavior: "smooth" });
    };
  }

  /* ============================================================
     SELECTION BRIDGE (bubble <-> table)
     ============================================================ */
  let _selected = null;

  function selectStock(ticker) {
    if (_selected === ticker) {
      _selected = null;
      window._highlightBubble(null);
      window._highlightRow(null);
    } else {
      _selected = ticker;
      window._highlightBubble(ticker);
      window._highlightRow(ticker);
    }
  }
})();

